class Trie {
    struct Node {
        Node* child[26];
        bool end;
        Node() : end(false) {
            for (int i = 0; i < 26; ++i) child[i] = nullptr;
        }
    };
    Node* root;
public:
    Trie() {
        root = new Node();
    }

    void insert(string word) {
        Node* p = root;
        for (char ch : word) {
            int idx = ch - 'a';
            if (!p->child[idx]) p->child[idx] = new Node();
            p = p->child[idx];
        }
        p->end = true;
    }

    bool search(string word) {
        Node* p = root;
        for (char ch : word) {
            int idx = ch - 'a';
            if (!p->child[idx]) return false;
            p = p->child[idx];
        }
        return p->end;
    }

    bool startsWith(string prefix) {
        Node* p = root;
        for (char ch : prefix) {
            int idx = ch - 'a';
            if (!p->child[idx]) return false;
            p = p->child[idx];
        }
        return true;
    }
};
